import React from 'react';
import { Streamlit, withStreamlitConnection } from 'streamlit-component-lib';
import { Html5QrcodeScanner } from 'html5-qrcode';

class BarcodeScannerComponent extends React.Component {
  constructor(props) {
    super(props);
    this.html5QrcodeScanner = null;
  }

  componentDidMount() {
    // Fonction de succès du scan
    const onScanSuccess = (decodedText, decodedResult) => {
      console.log(`Code trouvé ! ${decodedText}`, decodedResult);
      // Envoyer la valeur à Streamlit
      Streamlit.setComponentValue(decodedText);

      // Arrêter le scanner proprement
      if (this.html5QrcodeScanner && this.html5QrcodeScanner.getState() === 2) { // 2 = SCANNING
        this.html5QrcodeScanner.clear().catch(error => {
          console.error("Échec de l'arrêt du scanner.", error);
        });
      }
    };

    // Fonction d'échec (ignorée)
    const onScanFailure = (error) => {
      // console.warn(`Erreur de scan = ${error}`);
    };

    // Configuration du scanner
    const config = {
      fps: 10,
      qrbox: { width: 250, height: 150 },
      facingMode: "environment"
    };

    // Initialiser et rendre le scanner
    if (!this.html5QrcodeScanner) {
      this.html5QrcodeScanner = new Html5QrcodeScanner("reader", config, false);
      this.html5QrcodeScanner.render(onScanSuccess, onScanFailure);
    }
    
    // Ajuster la hauteur du cadre pour Streamlit
    Streamlit.setFrameHeight(400);
  }

  componentWillUnmount() {
    // S'assurer que le scanner est arrêté lorsque le composant est détruit
    if (this.html5QrcodeScanner) {
      this.html5QrcodeScanner.clear().catch(error => {
        console.error("Échec de l'arrêt du scanner lors du démontage.", error);
      });
    }
  }

  render() {
    return <div id="reader" style={{ width: '100%' }} />;
  }
}

// Exporter le composant "connecté" à Streamlit
export default withStreamlitConnection(BarcodeScannerComponent);
